	private static readonly Dictionary<string, GeometryGroup> StrokeCache = new Dictionary<string, GeometryGroup>();
	private static readonly Dictionary<string, GeometryGroup> FillCache = new Dictionary<string, GeometryGroup>();

	private static double Parse(string s)
	{
		return double.Parse(s, CultureInfo.InvariantCulture);
	}

	private static GeometryGroup StrokeGeometry(string[] parts)
	{
		GeometryGroup group = new GeometryGroup
		{
			FillRule = FillRule.Nonzero
		};
		foreach (string part in parts)
		{
			char kind = part[0];
			string[] values = part.Substring(2).Split(',');
			switch (kind)
			{
			case 'p':
				group.Children.Add(Geometry.Parse(values[0]));
				break;
			case 'r':
				group.Children.Add(new RectangleGeometry(new Rect(Parse(values[0]), Parse(values[1]), Parse(values[2]), Parse(values[3])), Parse(values[4]), Parse(values[4])));
				break;
			case 'c':
				group.Children.Add(new EllipseGeometry(new System.Windows.Point(Parse(values[0]), Parse(values[1])), Parse(values[2]), Parse(values[2])));
				break;
			case 'l':
				group.Children.Add(new LineGeometry(new System.Windows.Point(Parse(values[0]), Parse(values[1])), new System.Windows.Point(Parse(values[2]), Parse(values[3]))));
				break;
			}
		}
		group.Freeze();
		return group;
	}

	private static GeometryGroup FillGeometry(string[] parts)
	{
		GeometryGroup group = new GeometryGroup
		{
			FillRule = FillRule.Nonzero
		};
		foreach (string part in parts)
		{
			// Geometry.Parse 返回 WPF 缓存的冻结实例，先 Clone 再设 Transform，否则二次渲染抛只读异常
			Geometry geometry = Geometry.Parse(part.Substring(2)).Clone();
			geometry.Transform = new ScaleTransform(24.0 / 256.0, 24.0 / 256.0);
			group.Children.Add(geometry);
		}
		group.Freeze();
		return group;
	}

	private static System.Windows.Media.Brush TonalBrush(System.Windows.Media.Color color)
	{
		byte Adjust(byte value, int delta)
		{
			return (byte)Math.Max(0, Math.Min(255, (int)value + delta));
		}
		LinearGradientBrush brush = new LinearGradientBrush(
			System.Windows.Media.Color.FromArgb(color.A, Adjust(color.R, 26), Adjust(color.G, 26), Adjust(color.B, 26)),
			System.Windows.Media.Color.FromArgb(color.A, Adjust(color.R, -18), Adjust(color.G, -18), Adjust(color.B, -18)),
			50.0);
		brush.GradientStops.Insert(1, new GradientStop(color, 0.55));
		return brush;
	}

	private static FrameworkElement[] ColorfulGeometry(string[] parts)
	{
		List<FrameworkElement> elements = new List<FrameworkElement>();
		foreach (string part in parts)
		{
			char kind = part[0];
			string[] values = part.Substring(2).Split(new char[1] { ',' }, 2);
			System.Windows.Media.Color color = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(values[0]);
			Brush brush = (kind == 'Q' ? new SolidColorBrush(color) : (Brush)TonalBrush(color));
			brush.Freeze();
			string data = values[1];
			switch (kind)
			{
			case 'P':
			{
				Path path = new Path
				{
					Data = Geometry.Parse(data),
					Fill = brush
				};
				elements.Add(path);
				break;
			}
			case 'R':
			{
				string[] rc = data.Split(',');
				Rectangle rectangle = new Rectangle
				{
					Width = Parse(rc[2]),
					Height = Parse(rc[3]),
					RadiusX = Parse(rc[4]),
					RadiusY = Parse(rc[4]),
					Fill = brush
				};
				Canvas.SetLeft(rectangle, Parse(rc[0]));
				Canvas.SetTop(rectangle, Parse(rc[1]));
				elements.Add(rectangle);
				break;
			}
			case 'C':
			{
				string[] cc = data.Split(',');
				Ellipse ellipse = new Ellipse
				{
					Width = Parse(cc[2]) * 2.0,
					Height = Parse(cc[2]) * 2.0,
					Fill = brush
				};
				Canvas.SetLeft(ellipse, Parse(cc[0]) - Parse(cc[2]));
				Canvas.SetTop(ellipse, Parse(cc[1]) - Parse(cc[2]));
				elements.Add(ellipse);
				break;
			}
			case 'Q':
			{
				Path path = new Path
				{
					Data = Geometry.Parse(data),
					Stroke = brush,
					StrokeThickness = 1.9,
					StrokeStartLineCap = PenLineCap.Round,
					StrokeEndLineCap = PenLineCap.Round,
					StrokeLineJoin = PenLineJoin.Round
				};
				elements.Add(path);
				break;
			}
			}
		}
		return elements.ToArray();
	}

	private static Path StrokeIcon(Def def, System.Windows.Media.Brush stroke)
	{
		string key = "s" + def.Line.GetHashCode().ToString();
		if (!StrokeCache.TryGetValue(key, out GeometryGroup group))
		{
			group = StrokeGeometry(def.Line);
			StrokeCache[key] = group;
		}
		return new Path
		{
			Data = group,
			Stroke = stroke,
			StrokeThickness = 1.9,
			Stretch = Stretch.Uniform,
			Width = 24.0,
			Height = 24.0,
			StrokeStartLineCap = PenLineCap.Round,
			StrokeEndLineCap = PenLineCap.Round,
			StrokeLineJoin = PenLineJoin.Round
		};
	}

	private static Path FillIcon(Def def, System.Windows.Media.Brush fill)
	{
		string key = "f" + def.Fill.GetHashCode().ToString();
		if (!FillCache.TryGetValue(key, out GeometryGroup group))
		{
			group = FillGeometry(def.Fill);
			FillCache[key] = group;
		}
		return new Path
		{
			Data = group,
			Fill = fill,
			Stretch = Stretch.Uniform,
			Width = 24.0,
			Height = 24.0
		};
	}

	private static readonly Dictionary<string, GeometryGroup> AntCache = new Dictionary<string, GeometryGroup>();

	private static GeometryGroup AntGeometry(string path)
	{
		if (!AntCache.TryGetValue(path, out GeometryGroup group))
		{
			Geometry geometry = Geometry.Parse(path).Clone();
			geometry.Transform = new ScaleTransform(24.0 / 1024.0, 24.0 / 1024.0);
			group = new GeometryGroup
			{
				FillRule = FillRule.EvenOdd
			};
			group.Children.Add(geometry);
			group.Freeze();
			AntCache[path] = group;
		}
		return group;
	}

	private static Path AntIcon(Def def, int pack, System.Windows.Media.Brush brush)
	{
		string path = pack == 4 ? (def.AntF ?? def.AntO) : (def.AntO ?? def.AntF);
		return new Path
		{
			Data = AntGeometry(path),
			Fill = brush,
			Stretch = Stretch.Uniform,
			Width = 24.0,
			Height = 24.0
		};
	}

	private static readonly Dictionary<string, GeometryGroup> FluentCache = new Dictionary<string, GeometryGroup>();

	private static Path FluentIcon(string kind, System.Windows.Media.Brush fill)
	{
		if (!FluentPaths.TryGetValue(kind, out string path))
		{
			path = FluentPaths["apps"];
		}
		if (!FluentCache.TryGetValue(path, out GeometryGroup group))
		{
			Geometry geometry = Geometry.Parse(path).Clone();
			geometry.Transform = Transform.Identity;
			group = new GeometryGroup
			{
				FillRule = FillRule.Nonzero
			};
			group.Children.Add(geometry);
			group.Freeze();
			FluentCache[path] = group;
		}
		return new Path
		{
			Data = group,
			Fill = fill,
			Stretch = Stretch.Uniform,
			Width = 24.0,
			Height = 24.0
		};
	}

	private static readonly Dictionary<string, GeometryGroup> FeatherCache = new Dictionary<string, GeometryGroup>();

	private static Path FeatherIcon(string kind, System.Windows.Media.Brush stroke)
	{
		if (!FeatherParts.TryGetValue(kind, out string[] parts))
		{
			parts = FeatherParts["apps"];
		}
		string key = "t" + string.Join("|", parts).GetHashCode().ToString();
		if (!FeatherCache.TryGetValue(key, out GeometryGroup group))
		{
			group = StrokeGeometry(parts);
			FeatherCache[key] = group;
		}
		return new Path
		{
			Data = group,
			Stroke = stroke,
			StrokeThickness = 2.0,
			Stretch = Stretch.Uniform,
			Width = 24.0,
			Height = 24.0,
			StrokeStartLineCap = PenLineCap.Round,
			StrokeEndLineCap = PenLineCap.Round,
			StrokeLineJoin = PenLineJoin.Round
		};
	}

	// 渲染一枚内置图标；size 为输出边长。
	// pack 0=Lucide 线条 / 1=Phosphor 填充 / 2=Win11 Fluent 官方 / 3=Feather 线条（全部无背景底）
	// 内容统一绘制在 24×24 画布上，再缩放到输出边长的 0.85 倍并居中——与应用图标视觉尺寸一致
	public static FrameworkElement Glyph(string kind, int pack, int accent, System.Windows.Media.Brush text, double size = 44.0)
	{
		if (!Icons.TryGetValue(kind, out Def def))
		{
			return new Grid
			{
				Width = size,
				Height = size
			};
		}
		int p = Math.Max(0, Math.Min(Names.Length - 1, pack));
		Canvas canvas = new Canvas
		{
			Width = 24.0,
			Height = 24.0
		};
		if (p == 2)
		{
			System.Windows.Media.Color textColor = (text as SolidColorBrush)?.Color ?? System.Windows.Media.Colors.White;
			canvas.Children.Add(FluentIcon(kind, TonalBrush(textColor)));
		}
		else if (p == 3)
		{
			canvas.Children.Add(FeatherIcon(kind, text));
		}
		else if (p == 1)
		{
			System.Windows.Media.Color textColor = (text as SolidColorBrush)?.Color ?? System.Windows.Media.Colors.White;
			canvas.Children.Add(FillIcon(def, TonalBrush(textColor)));
		}
		else
		{
			canvas.Children.Add(StrokeIcon(def, text));
		}
		Viewbox content = new Viewbox
		{
			Width = size * 0.85,
			Height = size * 0.85,
			Stretch = Stretch.Uniform,
			HorizontalAlignment = HorizontalAlignment.Center,
			VerticalAlignment = VerticalAlignment.Center,
			Child = canvas
		};
		Grid grid = new Grid
		{
			Width = size,
			Height = size
		};
		grid.Children.Add(content);
		return grid;
	}
}
